package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC4", "RC2", "Blowfish", "MD5", "SHA1", "NULL"}

weak_protocols := {"TLSv1.0", "TLSv1.1", "SSLv3", "SSLv2", "TLS1.0", "TLS1.1", "SSL3", "SSL2"}

algorithm_fields := {"encryption_algorithm", "cipher", "cipher_suite", "kms_key_spec", "encryption_key", "data_key_spec", "sse_algorithm", "crypto_key", "key_algorithm", "signature_algorithm"}

key_size_fields := {"key_size", "key_length", "key_bits", "bits", "size", "key_spec", "public_key_bytes", "minimum_key_size", "rsa_key_size", "ec_key_size"}

protocol_fields := {"tls_version", "ssl_protocol", "min_tls_version", "protocol_version", "security_policy", "policy_version"}

check_weak_algorithm(value) {
    value.ir_type == "String"
    upper(value.value) == weak_algorithms[_]
}

check_weak_protocol(value) {
    value.ir_type == "String"
    upper(value.value) == weak_protocols[_]
}

check_insufficient_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    to_number(value.value) < 128
}

check_rsa_weak_key(value) {
    value.ir_type == "String"
    contains(upper(value.value), "RSA")
    not contains(upper(value.value), "2048")
    not contains(upper(value.value), "3072")
    not contains(upper(value.value), "4096")
}

check_aes_weak_key(value) {
    value.ir_type == "String"
    contains(upper(value.value), "AES")
    not contains(upper(value.value), "128")
    not contains(upper(value.value), "192")
    not contains(upper(value.value), "256")
    count(split(value.value, "-")) == 1
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == algorithm_fields[_]
    check_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithm detected. Use modern encryption standards with sufficient key lengths. (CWE-326)"
    }
}

Glitch_Analysis[result] {
