package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC4", "RC2", "BLOWFISH", "MD5", "SHA1", "NULL", "MD5_CRYPT", "SHA", "SHA-1", "MD4"}

weak_protocols := {"TLSV1.0", "TLSV1.1", "SSLV3", "SSLV2", "TLS1.0", "TLS1.1", "SSL3", "SSL2", "TLSV1", "SSLV23"}

weak_cipher_patterns := {"CBC", "CBC_SHA", "RC4", "DES", "3DES", "MD5", "SHA1", "SHA_1", "NULL", "ANON", "EXPORT", "SSL"}

algorithm_fields := {"encryption_algorithm", "cipher", "cipher_suite", "kms_key_spec", "encryption_key", "data_key_spec", "sse_algorithm", "crypto_key", "key_algorithm", "signature_algorithm", "encrypt", "hash", "checksum", "digest"}

key_size_fields := {"key_size", "key_length", "key_bits", "bits", "size", "key_spec", "public_key_bytes", "minimum_key_size", "rsa_key_size", "ec_key_size", "salt_size"}

protocol_fields := {"tls_version", "ssl_protocol", "min_tls_version", "protocol_version", "security_policy", "policy_version", "version", "ssl"}

check_weak_algorithm_string(s) {
    upper(s) == weak_algorithms[_]
}

check_weak_protocol_string(s) {
    upper(s) == weak_protocols[_]
}

check_weak_cipher_in_string(s) {
    contains(upper(s), weak_cipher_patterns[_])
}

check_weak_algorithm(value) {
    value.ir_type == "String"
    check_weak_algorithm_string(value.value)
}

check_weak_protocol(value) {
    value.ir_type == "String"
    check_weak_protocol_string(value.value)
}

check_insufficient_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
    value.value > 0
} else {
    value.ir_type == "String"
    num := to_number(value.value)
    num < 128
    num > 0
}

is_weak_function_call(node) {
    node.name == "filter|hash"
    arg := node.args[_]
    arg.ir_type == "String"
    check_weak_algorithm_string(arg.value)
}

# Check any string value in the IR for weak crypto patterns
any_string_contains_weak(node) {
    node.ir_type == "String"
    check_weak_algorithm_string(node.value)
}

any_string_contains_weak(node) {
    node.ir_type == "String"
    check_weak_cipher_in_string(node.value)
}

# Recursively check all nested values in complex structures
nested_contains_weak(node) {
    any_string_contains_weak(node)
}

nested_contains_weak(node) {
    node.ir_type == "Array"
    elem := node.value[_]
    nested_contains_weak(elem)
}

nested_contains_weak(node) {
    node.ir_type == "Hash"
    kv := node.value[_]
    nested_contains_weak(kv.value)
}

nested_contains_weak(node) {
    node.ir_type == "KeyValue"
    nested_contains_weak(node.value)
}

nested_contains_weak(node) {
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    nested_contains_weak(arg)
}

nested_contains_weak(node) {
    node.ir_type == "MethodCall"
    nested_contains_weak(node.receiver)
}

nested_contains_weak(node) {
    node.ir_type == "Access"
    nested_contains_weak(node.left)
}

nested_contains_weak(node) {
    node.ir_type in {"Or", "And", "Sum", "Equal", "NotEqual", "LessThan", "LessThanOrEqual", "GreaterThan", "GreaterThanOrEqual", "Subtract", "Multiply", "Divide", "Modulo", "Power", "RightShift", "LeftShift", "BitwiseAnd", "BitwiseOr", "BitwiseXor", "Assign"}
    nested_contains_weak(node.left)
}

nested_contains_weak(node) {
    node.ir_type in {"Or", "And", "Sum", "Equal", "NotEqual", "LessThan", "LessThanOrEqual", "GreaterThan", "GreaterThanOrEqual", "Subtract", "Multiply", "Divide", "Modulo", "Power", "RightShift", "LeftShift", "BitwiseAnd", "BitwiseOr", "BitwiseXor", "Assign"}
    nested_contains_weak(node.right)
}

nested_contains_weak(node) {
    node.ir_type in {"Not", "Minus"}
    nested_contains_weak(node.expr)
}

# Check name for crypto-related fields
is_crypto_field(name) {
    upper(name) == algorithm_fields[_]
}

is_crypto_field(name) {
    upper(name) == key_size_fields[_]
}

is_crypto_field(name) {
    upper(name) == protocol_fields[_]
}

# Find any Attribute anywhere in the structure
all_deep_attrs(node) = attrs {
    attrs = {n |
        walk(node, [path, n])
        n.ir_type == "Attribute"
    }
}

# Find any Variable anywhere in the structure
all_deep_vars(node) = vars {
    vars = {n |
        walk(node, [path, n])
        n.ir_type == "Variable"
    }
}

# Find any FunctionCall anywhere in the structure
all_deep_func_calls(node) = funcs {
    funcs = {n |
        walk(node, [path, n])
        n.ir_type == "FunctionCall"
    }
}

# Find any nested structure with crypto field name
find_crypto_named_value(node) = result {
    walk(node, [path, n])
    n.ir_type in {"Attribute", "Variable", "KeyValue"}
    is_crypto_field(n.name)
    result := {"field": n.name, "value": n.value, "node": n}
}

# Main detection: Function calls with weak algorithms (e.g., hash('sha1'))
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    funcs := all_deep_func_calls(parent)
    func := funcs[_]
    is_weak_function_call(func)

    result := {
        "type": "sec_weak_crypt",
        "element": func,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithm in function call. Use modern hashing algorithms like SHA-256 or higher. (CWE-326)"
    }
}

# Main detection: Any Attribute with weak crypto value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := all_deep_attrs(parent)
    attr := attrs[_]
    nested_contains_weak(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic configuration detected in attribute. Use modern encryption standards. (CWE-326)"
    }
}

# Main detection: Any Variable with weak crypto value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := all_deep_vars(parent)
    v := vars[_]
    v.name == algorithm_fields[_]
    check_weak_cipher_in_string(v.value.value)

    result := {
        "type": "sec_weak_crypt",
        "element": v,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cipher suite configuration detected. Avoid CBC mode and weak hash algorithms. (CWE-326)"
    }
}

# Specific: Attribute named with crypto field containing weak algorithm
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := all_deep_attrs(parent)
    attr := attrs[_]
    is_crypto_field(attr.name)
    check_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithm detected. Use modern encryption standards with sufficient key lengths. (CWE-326)"
    }
}

# Specific: Attribute named with protocol field containing weak protocol
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := all_deep_attrs(parent)
    attr := attrs[_]
    attr.name == protocol_fields[_]
    check_weak_protocol(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Deprecated TLS/SSL protocol version detected. Enforce minimum TLS 1.2 or higher. (CWE-326)"
    }
}

# Specific: KeySize field with insufficient value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := all_deep_attrs(parent)
    attr := attrs[_]
    attr.name == key_size_fields[_]
    check_insufficient_key_size(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Insufficient key size detected. Symmetric keys should be at least 128 bits, asymmetric at least 2048 bits. (CWE-326)"
    }
}

